package apitest

// The goldens of TestJSONTextParsedSQL: the SQL of a JSONText's Number,
// at a path of two keys, and Time, at one, on each dialect (ADR 0165).
const (
	pgNumber = `SELECT "id" FROM "j_docs" WHERE CASE jsonb_typeof(jsonb_extract_path("attrs", $1, $2)) WHEN 'number' THEN (jsonb_extract_path_text("attrs", $3, $4))::numeric WHEN 'string' THEN CASE WHEN length(jsonb_extract_path_text("attrs", $5, $6)) <= 200 AND jsonb_extract_path_text("attrs", $7, $8) COLLATE "C" ~ '^-{0,1}(0|[1-9][0-9]*)([.][0-9]+){0,1}([eE][-+]{0,1}[0-9]{1,2}){0,1}$' THEN CAST(jsonb_extract_path_text("attrs", $9, $10) AS numeric) END END > $11 LIMIT 1`
	pgTime   = `SELECT "id" FROM "j_docs" WHERE CASE WHEN jsonb_typeof(jsonb_extract_path("attrs", $1)) = 'string' AND jsonb_extract_path_text("attrs", $2) COLLATE "C" ~ '^([1-9][0-9]{3}-(0[13578]|1[02])-(0[1-9]|[12][0-9]|3[01])|[1-9][0-9]{3}-(0[469]|11)-(0[1-9]|[12][0-9]|30)|[1-9][0-9]{3}-02-(0[1-9]|1[0-9]|2[0-8])|([1-9][0-9](0[48]|[2468][048]|[13579][26])|([2468][048]|[13579][26])00)-02-29)T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9}){0,1}(Z|[-+](0[0-9]|1[0-4]):[0-5][0-9])$' AND left(jsonb_extract_path_text("attrs", $3), 10) <> '9999-12-31' THEN CAST(jsonb_extract_path_text("attrs", $4) AS timestamptz) END = $5 LIMIT 1`
	myNumber = "SELECT `id` FROM `j_docs` WHERE CASE WHEN JSON_TYPE(JSON_EXTRACT(`attrs`, ?)) IN ('INTEGER', 'UNSIGNED INTEGER', 'DOUBLE', 'DECIMAL') THEN CAST(JSON_EXTRACT(`attrs`, ?) AS DOUBLE) WHEN JSON_TYPE(JSON_EXTRACT(`attrs`, ?)) = 'STRING' AND CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?))) <= 200 AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), '^-{0,1}(0|[1-9][0-9]*)([.][0-9]+){0,1}([eE][-+]{0,1}[0-9]{1,2}){0,1}$', 'c') AND NOT REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), '[^-+.0-9eE]', 'c') THEN CAST(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)) AS DOUBLE) END > ? LIMIT 1"
	myTime   = "SELECT `id` FROM `j_docs` WHERE CASE WHEN JSON_TYPE(JSON_EXTRACT(`attrs`, ?)) = 'STRING' AND REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), '^([1-9][0-9]{3}-(0[13578]|1[02])-(0[1-9]|[12][0-9]|3[01])|[1-9][0-9]{3}-(0[469]|11)-(0[1-9]|[12][0-9]|30)|[1-9][0-9]{3}-02-(0[1-9]|1[0-9]|2[0-8])|([1-9][0-9](0[48]|[2468][048]|[13579][26])|([2468][048]|[13579][26])00)-02-29)T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]([.][0-9]{1,9}){0,1}(Z|[-+](0[0-9]|1[0-4]):[0-5][0-9])$', 'c') AND NOT REGEXP_LIKE(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), '[^-+.:0-9TZ]', 'c') AND LEFT(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), 10) <> '9999-12-31' THEN CASE WHEN RIGHT(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), 1) = 'Z' THEN CAST(LEFT(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?))) - 1) AS DATETIME(6)) ELSE CAST(LEFT(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?))) - 6) AS DATETIME(6)) - INTERVAL ((CAST(SUBSTRING(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), -5, 2) AS SIGNED) * 60 + CAST(RIGHT(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), 2) AS SIGNED)) * IF(SUBSTRING(JSON_UNQUOTE(JSON_EXTRACT(`attrs`, ?)), -6, 1) = '-', -1, 1)) MINUTE END END = ? LIMIT 1"
	sqNumber = `SELECT "id" FROM "j_docs" WHERE CASE WHEN json_type("attrs", ?) IN ('integer', 'real') THEN json_extract("attrs", ?) WHEN json_type("attrs", ?) = 'text' AND length(json_extract("attrs", ?)) <= 200 AND json_valid(json_extract("attrs", ?)) AND json_extract("attrs", ?) NOT GLOB '*[^-+.0-9eE]*' AND json_extract("attrs", ?) NOT GLOB '*[eE]*[0-9][0-9][0-9]*' THEN CAST(json_extract("attrs", ?) AS REAL) END > ? LIMIT 1`
	sqTime   = `SELECT "id" FROM "j_docs" WHERE CASE WHEN json_type("attrs", ?) = 'text' AND json_extract("attrs", ?) GLOB '[1-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*' AND json_extract("attrs", ?) NOT GLOB '*[^-+.:0-9TZ]*' AND (json_extract("attrs", ?) GLOB '*Z' AND length(json_extract("attrs", ?)) <= 30 OR json_extract("attrs", ?) GLOB '*[-+][01][0-9]:[0-5][0-9]' AND substr(json_extract("attrs", ?), -5, 2) <= '14' AND length(json_extract("attrs", ?)) <= 35) AND strftime('%Y-%m-%dT%H:%M:%S', substr(json_extract("attrs", ?), 1, 19)) = substr(json_extract("attrs", ?), 1, 19) AND substr(json_extract("attrs", ?), 12, 2) <= '23' AND julianday(json_extract("attrs", ?)) IS NOT NULL AND substr(json_extract("attrs", ?), 1, 10) <> '9999-12-31' THEN strftime('%Y-%m-%d %H:%M:%S', substr(json_extract("attrs", ?), 1, 19) || ltrim(substr(json_extract("attrs", ?), 20), '.0123456789')) || '.' || substr(substr(json_extract("attrs", ?), 21, max(length(json_extract("attrs", ?)) - 20 - length(ltrim(substr(json_extract("attrs", ?), 20), '.0123456789')), 0)) || '000000000', 1, 9) || '+00:00' END = ? LIMIT 1`
)
